/* ═══ Review viewer: player bar, range, timecode formats, guides/mask, zoom, annotations, anchored comments, comments & fields panels, transcript/captions ═══ */
'use strict';
let VW=null;
const SPEEDS=[0.25,0.5,0.75,1,1.25,1.5,1.75];
const ANN_COLORS=['#ff4fa3','#ffd84f','#5ee87a','#ff9a3c'];
const EMOJIS=['👍','❤️','🔥','👏','😂','😮','😢','🙏','✅','👀','💯','🎉','🤔','👎','⭐','🚀'];
function guestName(){try{return localStorage.getItem('bm.review.guest')||''}catch(e){return''}}
function who(){return VW&&VW.share?(guestName()||'Guest'):ME.name}
function renderViewer(a,opt={}){const share=opt.share||null;const pr=proj(a.pid);const main=$('#main');const guest=!!share;
 const v=cur(a);const m=v.meta||{};VW={a,v,share,guest,fps:m.fps||30,dur:m.duration||0,speed:1,loop:false,range:{in:null,out:null},zoom:'fit',scale:1,pan:{x:0,y:0},tab:'comments',filters:new Set(),sort:'timecode',q:'',sel:null,comp:{tc:null,tcEnd:null,useTc:true,atts:[],vis:guest?'public':'public',ann:null},draw:{on:false,tool:'arrow',color:ANN_COLORS[0],shapes:[],redo:[]},showPins:S.prefs.showAnchored!==false,showAnn:S.prefs.showAnn!==false,cc:false,trx:false,fieldGroup:'all',fieldFilter:'none',fieldQ:'',siblings:[],idx:0,shownAnn:null,mediaURL:null,unread:new Set()};
 const sib=(share?share.items.map(item).filter(x=>x&&x.kind==='asset'):(S.prefs.flatten?descendants(a.pid,a.parent):children(a.pid,a.parent)).filter(x=>x.kind==='asset'));VW.siblings=sorted(sib);VW.idx=Math.max(0,VW.siblings.findIndex(x=>x.id===a.id));
 const seenName=who();if(!(a.seen||[]).includes(seenName)){a.seen=(a.seen||[]).concat(seenName);save()}
 const base=share?`#/s/${share.id}`:`#/p/${a.pid}${a.parent?'/f/'+a.parent:''}`;
 main.innerHTML=`<div class="vtop"><a class="ib" href="${base}" title="Back">${ico('back')}</a><div class="crumbs">${share?`${avatar(share.by)}<a href="${base}">${esc(share.title)}</a>`:crumbsFor(pr,a.parent?item(a.parent):null)}<i>›</i><button class="btn soft sm" id="vName" style="font-weight:600;max-width:320px"><span style="overflow:hidden;text-overflow:ellipsis">${esc(a.name)}</span>${a.versions.length>1?`<span class="pro">v${a.cur+1}</span>`:''}${ico('down')}</button></div><div class="nav"><button class="ib" id="vPrev" ${VW.idx>0?'':'disabled'}>${ico('prev')}</button><span>${VW.idx+1} of ${VW.siblings.length}</span><button class="ib" id="vNext" ${VW.idx<VW.siblings.length-1?'':'disabled'}>${ico('next')}</button></div>${share?(share.perms.downloads?`<button class="btn ghost sm" id="vDl">${ico('dl')}Download</button>`:''):`<button class="btn gold sm" id="vShare">${ico('share')}Share</button>`}<button class="ib" id="vSearch" title="Search comments">${ico('search')}</button><button class="ib ${S.prefs.panel?'on':''}" id="vInfo" title="${share?'Hide Asset Information':'Toggle Asset Info'} (⌥4)">${ico('info')}</button></div>
 <div class="viewer"><aside class="lpanel" id="lpanel"></aside><div class="vcol"><div class="stage paused" id="stage"><div class="bigplay">${ico('play')}</div></div><div class="tl" id="tl"><div class="buf"></div><div class="played" id="tlPlayed"></div><div class="range" id="tlRange" hidden></div><div id="tlMarks"></div><div class="ph" id="tlPh"></div><div class="hover" id="tlHover"></div></div><div class="ctl" id="ctl"></div></div><aside class="vpanel ${S.prefs.panel?'':'off'}" id="vpanel"></aside></div>`;
 buildStage();buildControls();buildPanel();buildLeft();
 $('#vName').onclick=e=>nameMenu(e.currentTarget);$('#vPrev').onclick=()=>stepAsset(-1);$('#vNext').onclick=()=>stepAsset(1);const sh=$('#vShare');if(sh)sh.onclick=()=>createShare(a.pid,[a.id]);const dl=$('#vDl');if(dl)dl.onclick=()=>downloadItems([a.id]);$('#vSearch').onclick=()=>{VW.tab='comments';buildPanel();const q=$('#cQ');if(q)q.focus()};$('#vInfo').onclick=()=>{S.prefs.panel=!S.prefs.panel;save();$('#vpanel').classList.toggle('off',!S.prefs.panel);$('#vInfo').classList.toggle('on',S.prefs.panel);layoutStage()};
 const onKey=e=>viewerKeys(e);document.addEventListener('keydown',onKey);const onResize=()=>layoutStage();addEventListener('resize',onResize);
 VIEW_CLEANUP=()=>{document.removeEventListener('keydown',onKey);removeEventListener('resize',onResize);if(VW&&VW.mediaURL)URL.revokeObjectURL(VW.mediaURL);if(VW&&VW.el){VW.el.pause();VW.el.src=''}VW=null};
 const cq=route().q.get('c');if(cq)setTimeout(()=>selectComment(cq),300)}
function stepAsset(d){const n=VW.siblings[VW.idx+d];if(!n)return;go(VW.share?`/s/${VW.share.id}/view/${n.id}`:'/view/'+n.id)}
/* ── stage ── */
async function buildStage(){const st=$('#stage');const {a,v}=VW;const m=v.meta||{};const file=await DB.loadMedia(v.id,v.media);if(!VW||VW.v!==v)return;
 const box=document.createElement('div');box.className='vbox';box.style.cssText='position:absolute;left:0;top:0;transform-origin:0 0';st.appendChild(box);VW.box=box;
 if(!file){box.innerHTML=`<div class="stillmsg" style="padding:40px;text-align:center">Media not available in this browser.<br><small>Reconnect the media folder, or re-upload this version.</small><br><br><button class="btn ghost sm" id="recon">Reconnect media folder</button></div>`;$('#recon').onclick=()=>DB.reconnectDir().then(()=>render());VW.w=640;VW.h=360;layoutStage();return}
 VW.mediaURL=URL.createObjectURL(file);
 if(m.type==='Video'||m.type==='Audio'){const el=document.createElement(m.type==='Video'?'video':'audio');el.src=VW.mediaURL;el.preload='auto';el.playsInline=true;el.style.cssText='display:block;width:100%;height:100%;background:#000';VW.el=el;box.appendChild(el);
  if(m.type==='Audio'){const img=document.createElement('img');img.className='still';img.style.cssText='position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.9';thumbURL(a).then(u=>{if(u)img.src=u});box.appendChild(img);el.style.cssText='position:absolute;left:0;right:0;bottom:0;height:0'}
  el.onloadedmetadata=()=>{VW.dur=el.duration||VW.dur;VW.w=el.videoWidth||1280;VW.h=el.videoHeight||720;layoutStage();updateTime();drawMarks()};el.ontimeupdate=updateTime;el.onplay=()=>{st.classList.remove('paused');$('#bPlay').innerHTML=ico('pause')};el.onpause=()=>{st.classList.add('paused');$('#bPlay').innerHTML=ico('play')};el.onended=()=>{if(VW.loop){el.currentTime=VW.range.in||0;el.play()}};el.onvolumechange=()=>{const b=$('#bMute');if(b)b.innerHTML=ico(el.muted||!el.volume?'mute':'vol')};
  st.onclick=e=>{if(e.target.closest('.cmtpin')||VW.draw.on)return;if(e.target===st||e.target===el||e.target.classList.contains('bigplay')||e.target.closest('.bigplay'))togglePlay()};st.ondblclick=e=>{if(!VW.draw.on)fullscreen()}}
 else if(m.type==='Image'){const img=document.createElement('img');img.className='still';img.src=VW.mediaURL;img.style.cssText='display:block;width:100%;height:100%';img.onload=()=>{VW.w=img.naturalWidth;VW.h=img.naturalHeight;layoutStage()};box.appendChild(img);$('#tl').style.display='none'}
 else{box.innerHTML=`<div class="stillmsg" style="padding:40px;text-align:center">${ico('doc')}<br>${esc(m.type||'File')} · ${fmtSize(m.size)}<br><br><button class="btn ghost sm" id="dlIt">Download to open</button></div>`;$('#dlIt').onclick=()=>downloadItems([a.id]);VW.w=640;VW.h=360;$('#tl').style.display='none';layoutStage()}
 const cv=document.createElement('canvas');cv.className='ann';box.appendChild(cv);VW.cv=cv;bindDrawing(cv);
 const ov=document.createElement('div');ov.className='overlays';ov.style.cssText='position:absolute;inset:0;pointer-events:none';box.appendChild(ov);VW.ov=ov;
 const cc=document.createElement('div');cc.className='cc';cc.hidden=true;st.appendChild(cc);VW.ccEl=cc;
 const zt=document.createElement('div');zt.className='zoomtip';zt.hidden=true;st.appendChild(zt);VW.zt=zt;
 st.onwheel=e=>{if(!(e.ctrlKey||e.metaKey))return;e.preventDefault();setZoom(VW.scale*(e.deltaY<0?1.1:0.9))};
 let pan=null;st.onpointerdown=e=>{if(VW.zoom!=='fit'&&VW.zoom!=='fill'&&!VW.draw.on&&!e.target.closest('.cmtpin')){pan={x:e.clientX,y:e.clientY,px:VW.pan.x,py:VW.pan.y};st.setPointerCapture(e.pointerId)}};st.onpointermove=e=>{if(pan){VW.pan={x:pan.px+e.clientX-pan.x,y:pan.py+e.clientY-pan.y};layoutStage()}};st.onpointerup=()=>pan=null;
 layoutStage()}
function layoutStage(){if(!VW||!VW.box)return;const st=$('#stage');const W=st.clientWidth,H=st.clientHeight;const w=VW.w||1280,h=VW.h||720;let s;if(VW.zoom==='fit')s=Math.min(W/w,H/h);else if(VW.zoom==='fill')s=Math.max(W/w,H/h);else s=VW.scale;const bw=w*s,bh=h*s;VW.scale=s;VW.box.style.width=bw+'px';VW.box.style.height=bh+'px';const x=(W-bw)/2+(VW.zoom==='fit'||VW.zoom==='fill'?0:VW.pan.x),y=(H-bh)/2+(VW.zoom==='fit'||VW.zoom==='fill'?0:VW.pan.y);VW.box.style.transform=`translate(${x}px,${y}px)`;if(VW.cv){VW.cv.width=Math.round(bw*devicePixelRatio);VW.cv.height=Math.round(bh*devicePixelRatio);VW.cv.style.width=bw+'px';VW.cv.style.height=bh+'px'}VW.zt.hidden=VW.zoom==='fit'||VW.zoom==='fill';VW.zt.textContent=Math.round(s*100)+'%';drawGuides();drawAnn();drawPins()}
function setZoom(z){if(z==='fit'||z==='fill'){VW.zoom=z;VW.pan={x:0,y:0}}else{VW.zoom='custom';VW.scale=Math.min(8,Math.max(.1,z))}layoutStage()}
function drawGuides(){const ov=VW.ov;if(!ov)return;ov.innerHTML='';const g=S.prefs.guide||'off';if(g==='off')return;const r={'2.35':2.35,'1.85':1.85,'16:9':16/9,'9:16':9/16,'4:3':4/3,'1:1':1}[g];const W=VW.box.clientWidth,H=VW.box.clientHeight;let gw=W,gh=W/r;if(gh>H){gh=H;gw=H*r}const x=(W-gw)/2,y=(H-gh)/2;const d=document.createElement('div');d.className='guide';d.style.cssText=`left:${x}px;top:${y}px;width:${gw}px;height:${gh}px`;ov.appendChild(d);if(S.prefs.mask){[[0,0,W,y],[0,y+gh,W,H-y-gh],[0,y,x,gh],[x+gw,y,W-x-gw,gh]].forEach(([l,t,w,h])=>{if(w<=0||h<=0)return;const m=document.createElement('div');m.className='mask';m.style.cssText=`left:${l}px;top:${t}px;width:${w}px;height:${h}px`;ov.appendChild(m)})}}
/* annotations */
function bindDrawing(cv){let cur=null;const pos=e=>{const r=cv.getBoundingClientRect();return[(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]};cv.onpointerdown=e=>{if(!VW.draw.on)return;e.preventDefault();cv.setPointerCapture(e.pointerId);cur={t:VW.draw.tool,c:VW.draw.color,p:[pos(e)]};if(cur.t!=='pen')cur.p.push(pos(e));VW.draw.shapes.push(cur);drawAnn()};cv.onpointermove=e=>{if(!cur)return;const p=pos(e);if(cur.t==='pen')cur.p.push(p);else cur.p[1]=p;drawAnn()};cv.onpointerup=()=>{if(cur){VW.draw.redo=[];cur=null;drawAnn();updateComposer()}}}
function drawShapes(ctx,shapes,W,H){ctx.lineCap='round';ctx.lineJoin='round';for(const s of shapes){ctx.strokeStyle=s.c;ctx.fillStyle=s.c;ctx.lineWidth=Math.max(2,W/300);const P=s.p.map(([x,y])=>[x*W,y*H]);ctx.beginPath();if(s.t==='pen'){P.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke()}else if(s.t==='rect'){const [[x1,y1],[x2,y2]]=P;ctx.strokeRect(Math.min(x1,x2),Math.min(y1,y2),Math.abs(x2-x1),Math.abs(y2-y1))}else{const [[x1,y1],[x2,y2]]=P;ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();if(s.t==='arrow'){const ang=Math.atan2(y2-y1,x2-x1),L=Math.max(10,W/60);ctx.beginPath();ctx.moveTo(x2,y2);ctx.lineTo(x2-L*Math.cos(ang-.5),y2-L*Math.sin(ang-.5));ctx.lineTo(x2-L*Math.cos(ang+.5),y2-L*Math.sin(ang+.5));ctx.closePath();ctx.fill()}}}}
function drawAnn(){const cv=VW&&VW.cv;if(!cv)return;const ctx=cv.getContext('2d');ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);const W=cv.clientWidth,H=cv.clientHeight;ctx.clearRect(0,0,W,H);if(VW.draw.on||VW.draw.shapes.length)drawShapes(ctx,VW.draw.shapes,W,H);else if(VW.shownAnn&&VW.showAnn)drawShapes(ctx,VW.shownAnn,W,H)}
function drawPins(){if(!VW||!VW.box)return;$$('.cmtpin',VW.box).forEach(p=>p.remove());if(!VW.showPins||VW.draw.on)return;const t=curTime();const list=visibleComments().filter(c=>c.ann&&c.tc!=null&&Math.abs(c.tc-t)<=0.5/VW.fps*VW.fps*0.5+0.25);list.forEach((c,i)=>{const pts=c.ann.shapes.flatMap(s=>s.p);if(!pts.length)return;const cx=pts.reduce((n,p)=>n+p[0],0)/pts.length,cy=pts.reduce((n,p)=>n+p[1],0)/pts.length;const pin=document.createElement('div');pin.className='cmtpin';pin.style.left=cx*100+'%';pin.style.top=cy*100+'%';pin.innerHTML=`<span>${allComments().indexOf(c)+1}</span>`;pin.onclick=e=>{e.stopPropagation();selectComment(c.id)};VW.box.appendChild(pin)})}
/* ── controls ── */
function buildControls(){const c=$('#ctl');const {share}=VW;const hd=(VW.v.meta.h||0)>=720;c.innerHTML=`<button class="ib" id="bRangeIn" title="Set range start (I)"><svg viewBox="0 0 24 24"><path d="M6 4v16M6 12h12M14 8l4 4-4 4"/></svg></button><button class="ib" id="bRangeOut" title="Set range end (O)"><svg viewBox="0 0 24 24"><path d="M18 4v16M18 12H6M10 8l-4 4 4 4"/></svg></button><button class="ib" id="bPlay" title="Play (Space)">${ico('play')}</button><button class="ib" id="bLoop" title="Loop">${ico('loop')}</button><button class="spd" id="bSpeed" title="Playback speed">1.0×</button><span class="vol"><button class="ib" id="bMute" title="Mute (M)">${ico('vol')}</button><input type="range" min="0" max="1" step=".02" value="1" id="vol"></span><div class="tc"><input id="tcIn" value="00:00:00:00" spellcheck="false"><button class="dd" id="tcMode" title="Time format">${ico('down')}</button></div>${share&&!share.perms.captions?'':`<button class="ib ${VW.cc?'on':''}" id="bCC" title="Captions">${ico('cc')}</button>`}${share&&!share.perms.transcripts?'':`<button class="ib" id="bTrx" title="Transcript (⌥3)">${ico('trx')}</button>`}<button class="ib ${VW.showPins?'on':''}" id="bPins" title="Anchored comments">${ico('pin')}</button><button class="ib" id="bSet" title="Viewer Settings" style="position:relative">${ico('gear')}${hd?'<span class="hd">HD</span>':''}</button><button class="ib" id="bFull" title="Fullscreen (F)">${ico('full')}</button>`;
 $('#bPlay').onclick=togglePlay;$('#bLoop').onclick=()=>{VW.loop=!VW.loop;$('#bLoop').classList.toggle('on',VW.loop);if(VW.el)VW.el.loop=VW.loop&&VW.range.in==null};$('#bSpeed').onclick=e=>menu(e.currentTarget,SPEEDS.map(s=>({n:s.toFixed(2)+'×',tick:true,on:VW.speed===s,fn:()=>setSpeed(s)})),{above:true,w:120});$('#bMute').onclick=()=>{if(VW.el)VW.el.muted=!VW.el.muted};$('#vol').oninput=e=>{if(VW.el){VW.el.volume=+e.target.value;VW.el.muted=false}};
 $('#tcIn').onkeydown=e=>{if(e.key==='Enter'){const t=parseTC(e.target.value,VW.fps);if(t!=null)seek(t);e.target.blur()}if(e.key==='Escape')e.target.blur()};$('#tcIn').onfocus=e=>e.target.select();$('#tcIn').onblur=updateTime;
 $('#tcMode').onclick=e=>menu(e.currentTarget,[{h:'Time format'},{n:'Frames',tick:true,on:S.prefs.tcmode==='frames',fn:()=>setTcMode('frames')},{n:'Standard',tick:true,on:S.prefs.tcmode==='standard',fn:()=>setTcMode('standard')},{n:'Timecode',tick:true,on:S.prefs.tcmode==='timecode',fn:()=>setTcMode('timecode')}],{above:true});
 $('#bRangeIn').onclick=()=>setRange('in');$('#bRangeOut').onclick=()=>setRange('out');const cc=$('#bCC');if(cc)cc.onclick=toggleCC;const tx=$('#bTrx');if(tx)tx.onclick=toggleTranscript;$('#bPins').onclick=()=>{VW.showPins=!VW.showPins;S.prefs.showAnchored=VW.showPins;save();$('#bPins').classList.toggle('on',VW.showPins);drawPins()};$('#bSet').onclick=e=>viewerSettings(e.currentTarget);$('#bFull').onclick=fullscreen;
 const tl=$('#tl');tl.onpointerdown=e=>{if(e.target.classList.contains('mk'))return;const r=tl.getBoundingClientRect();const f=ev=>Math.min(1,Math.max(0,(ev.clientX-r.left)/r.width))*VW.dur;seek(f(e));const mv=ev=>seek(f(ev));const up=()=>{removeEventListener('pointermove',mv);removeEventListener('pointerup',up)};addEventListener('pointermove',mv);addEventListener('pointerup',up)};tl.onmousemove=e=>{const r=tl.getBoundingClientRect();const t=Math.min(1,Math.max(0,(e.clientX-r.left)/r.width))*VW.dur;const h=$('#tlHover');h.style.left=(e.clientX-r.left)+'px';h.textContent=fmtTC(t,VW.fps,S.prefs.tcmode)};
 setTcMode(S.prefs.tcmode||'timecode')}
const curTime=()=>VW&&VW.el?VW.el.currentTime:0;
function togglePlay(){const el=VW.el;if(!el)return;if(el.paused){if(VW.range.out!=null&&el.currentTime>=VW.range.out-0.01)el.currentTime=VW.range.in||0;el.play().catch(()=>{})}else el.pause()}
function seek(t){if(!VW.el)return;VW.el.currentTime=Math.min(VW.dur||1e9,Math.max(0,t));updateTime()}
function stepFrames(n){if(!VW.el)return;VW.el.pause();seek(curTime()+n/VW.fps)}
function setSpeed(s){VW.speed=s;if(VW.el)VW.el.playbackRate=s;$('#bSpeed').textContent=s.toFixed(s===1?1:2).replace(/0$/,'')+'×'}
function setTcMode(m){S.prefs.tcmode=m;save();updateTime();drawMarks()}
function setRange(k){const t=curTime();if(k==='in'){VW.range.in=t;if(VW.range.out!=null&&VW.range.out<=t)VW.range.out=null}else{VW.range.out=t;if(VW.range.in!=null&&VW.range.in>=t)VW.range.in=null}VW.comp.tcEnd=VW.range.out;if(VW.range.in!=null)VW.comp.tc=VW.range.in;const r=$('#tlRange');const a=VW.range.in||0,b=VW.range.out!=null?VW.range.out:VW.dur;r.hidden=VW.range.in==null&&VW.range.out==null;r.style.left=a/VW.dur*100+'%';r.style.width=(b-a)/VW.dur*100+'%';$('#bRangeIn').classList.toggle('on',VW.range.in!=null);$('#bRangeOut').classList.toggle('on',VW.range.out!=null);updateComposer()}
function clearRange(){VW.range={in:null,out:null};VW.comp.tcEnd=null;$('#tlRange').hidden=true;$('#bRangeIn').classList.remove('on');$('#bRangeOut').classList.remove('on');updateComposer()}
function updateTime(){if(!VW)return;const t=curTime();const el=$('#tcIn');if(el&&document.activeElement!==el)el.value=fmtTC(t,VW.fps,S.prefs.tcmode);const ph=$('#tlPh'),pl=$('#tlPlayed');if(ph&&VW.dur){ph.style.left=t/VW.dur*100+'%';pl.style.width=t/VW.dur*100+'%'}if(VW.el&&!VW.el.paused&&VW.range.out!=null&&t>=VW.range.out){if(VW.loop)VW.el.currentTime=VW.range.in||0;else VW.el.pause()}if(VW.comp.useTc&&!VW.comp.locked){VW.comp.tc=VW.range.in!=null?VW.range.in:t;const ch=$('#tchip');if(ch)ch.firstChild.textContent=chipLabel()}if(VW.cc)updateCC(t);if(VW.trx)highlightTranscript(t);drawPins();if(VW.shownAnn&&VW.shownAt!=null&&Math.abs(VW.shownAt-t)>0.3){VW.shownAnn=null;drawAnn()}}
function chipLabel(){const a=VW.comp.tc||0;const s=fmtTC(a,VW.fps,S.prefs.tcmode);return VW.comp.tcEnd!=null?s+' – '+fmtTC(VW.comp.tcEnd,VW.fps,S.prefs.tcmode):s}
function fullscreen(){const el=$('.vcol');if(document.fullscreenElement)document.exitFullscreen();else if(el.requestFullscreen)el.requestFullscreen()}
function viewerSettings(anchor){const p=S.prefs;const items=[{h:'Quality'},...['1080p HD','720p HD','540p SD','360p SD','Auto'].map(q=>({n:q,tick:true,on:(p.quality||'auto')===q,fn:()=>{p.quality=q;save();toast('Playing the original file — quality setting saved')}})),'-',{h:'Guides'},...['2.35','1.85','16:9','9:16','4:3','1:1','off'].map(g=>({n:g==='off'?'Off':g,tick:true,on:(p.guide||'off')===g,fn:()=>{p.guide=g;save();drawGuides()}})),{n:'Show Mask',toggle:!!p.mask,keep:true,fn:(e,el)=>{p.mask=!p.mask;save();$('.tog',el).classList.toggle('on',p.mask);drawGuides()}},'-',{h:'Zoom'},{n:'Fit',kbd:'T',fn:()=>setZoom('fit')},{n:'Fill',kbd:'Y',fn:()=>setZoom('fill')},{n:'Zoom In',kbd:'+',fn:()=>setZoom(VW.scale*1.25)},{n:'Zoom Out',kbd:'-',fn:()=>setZoom(VW.scale/1.25)},{n:'Zoom to 100%',kbd:'⌘0',fn:()=>setZoom(1)},'-',{h:'View on Asset'},{n:'Anchored Comments',toggle:VW.showPins,keep:true,fn:(e,el)=>{VW.showPins=!VW.showPins;p.showAnchored=VW.showPins;save();$('.tog',el).classList.toggle('on',VW.showPins);$('#bPins').classList.toggle('on',VW.showPins);drawPins()}},{n:'Annotations',toggle:VW.showAnn,keep:true,fn:(e,el)=>{VW.showAnn=!VW.showAnn;p.showAnn=VW.showAnn;save();$('.tog',el).classList.toggle('on',VW.showAnn);drawAnn()}},'-',{n:'Set Frame as Thumb',ic:'img',fn:setFrameThumb,dis:!!VW.guest},{n:'Download Still',ic:'cam',fn:downloadStill}];menu(anchor,items,{above:true,w:230})}
function frameCanvas(withAnn){const el=VW.el;if(!el||!el.videoWidth)return null;const c=document.createElement('canvas');c.width=el.videoWidth;c.height=el.videoHeight;const x=c.getContext('2d');x.drawImage(el,0,0);if(withAnn)drawShapes(x,withAnn,c.width,c.height);return c}
function downloadStill(){const c=frameCanvas(VW.shownAnn);if(!c)return toast('No frame to capture');c.toBlob(b=>dlBlob(b,`${VW.a.name} ${fmtTC(curTime(),VW.fps,'timecode').replace(/[:;]/g,'.')}.png`),'image/png')}
async function setFrameThumb(){const file=await DB.loadMedia(VW.v.id,VW.v.media);if(!file)return;const b=await makeThumb(file,'Video',curTime());if(b){await DB.put('thumbs',VW.v.id,b);delete thumbCache[VW.v.id];toast('Thumbnail updated')}}
function nameMenu(anchor){const {a,share}=VW;const items=share?[{n:'Download',ic:'dl',dis:!share.perms.downloads,fn:()=>downloadItems([a.id])},{n:'Download Still',ic:'cam',fn:downloadStill},{n:'Copy link',ic:'link',fn:()=>copyText(location.href,'Link copied')}]:[{n:'Create Share Link',ic:'share',fn:()=>createShare(a.pid,[a.id])},{n:'Add to Share Links',ic:'link',sub:ico('chev'),keep:true,fn:(e,el)=>addToShareMenu(el,[a.id],S.shares.filter(s=>s.pid===a.pid))},{n:'Open on Desktop',ic:'desktop',fn:()=>openOnDesktop(a)},{n:'Copy Asset URL',ic:'link',fn:()=>copyText(APP_PATH+'#/view/'+a.id,'URL copied')},{n:'Download',ic:'dl',fn:()=>downloadItems([a.id])},{n:'Download Still',ic:'cam',fn:downloadStill},{n:'Rename',ic:'edit',fn:()=>prompt2('Rename','Name',a.name,n=>{if(n){a.name=n;save();render()}})},{n:'Set Frame as Thumb',ic:'img',fn:setFrameThumb},{n:'Link to pipeline card',ic:'pipeline',fn:()=>linkPipeline(a)},'-',{h:`Versions (${a.versions.length})`},...a.versions.map((v,i)=>({n:`v${i+1} · ${v.srcName}`,sub:fmtDate(v.created),tick:true,on:i===a.cur,fn:()=>{a.cur=i;save();render()}})),{n:'Upload New Version',ic:'layers',fn:()=>pickVersion(a)},...(a.versions.length>1?[{n:`Delete v${a.cur+1}`,ic:'trash',danger:true,fn:()=>confirmBox('Delete this version?','The media file for this version is removed.','Delete',async()=>{const v=a.versions.splice(a.cur,1)[0];await DB.removeMedia(v.id,v.media);a.cur=a.versions.length-1;save();render()})}]:[]),'-',{n:'Delete',ic:'trash',danger:true,fn:()=>deleteItems([a.id])}];if(!share&&a.versions.length>1&&!(share&&!share.perms.allVersions)){}menu(anchor,items,{w:260})}
/* ── keys ── */
function viewerKeys(e){if(!VW)return;const tag=(e.target.tagName||'').toLowerCase();if(tag==='input'||tag==='textarea'||e.target.isContentEditable)return;const k=e.key;const el=VW.el;const stop=()=>e.preventDefault();
 if(k===' '||k==='k'){stop();togglePlay()}else if(k==='j'){if(el){el.playbackRate=Math.max(.25,VW.speed=VW.speed>1?1:VW.speed);seek(curTime()-1)}}else if(k==='l'){if(el)seek(curTime()+1)}else if(k==='ArrowLeft'){stop();stepFrames(e.shiftKey?-10:-1)}else if(k==='ArrowRight'){stop();stepFrames(e.shiftKey?10:1)}else if(k==='ArrowUp'||k==='ArrowDown'){stop();jumpComment(k==='ArrowUp'?-1:1)}else if(k==='Home')seek(0);else if(k==='End')seek(VW.dur);else if(k==='i'&&e.altKey)clearRange();else if(k==='o'&&e.altKey)clearRange();else if(k==='i')setRange('in');else if(k==='o')setRange('out');else if(k==='m'){if(el)el.muted=!el.muted}else if(k==='f')fullscreen();else if(k==='L')$('#bLoop').click();else if(k==='c'){stop();const t=$('#cText');if(t)t.focus()}else if(k==='d'){stop();toggleDraw()}else if(k==='t')setZoom('fit');else if(k==='y')setZoom('fill');else if(k==='+'||k==='=')setZoom(VW.scale*1.25);else if(k==='-')setZoom(VW.scale/1.25);else if(k==='0'&&(e.metaKey||e.ctrlKey)){stop();setZoom(1)}else if(k==='g'){const gs=['off','2.35','1.85','16:9','9:16','4:3','1:1'];S.prefs.guide=gs[(gs.indexOf(S.prefs.guide||'off')+1)%gs.length];save();drawGuides();toast('Guides: '+S.prefs.guide)}else if(k==='4'&&e.altKey){$('#vInfo').click()}else if(k==='3'&&e.altKey){toggleTranscript()}else if(k==='[')stepAsset(-1);else if(k===']')stepAsset(1);else if(k==='Escape'&&!document.fullscreenElement){if(e.handledEsc)return;if(VW.draw.on)toggleDraw(false);else go(VW.share?`/s/${VW.share.id}`:`/p/${VW.a.pid}${VW.a.parent?'/f/'+VW.a.parent:''}`)}}
function jumpComment(d){const list=visibleComments().filter(c=>c.tc!=null).sort((a,b)=>a.tc-b.tc);const t=curTime();const c=d>0?list.find(c=>c.tc>t+0.02):list.slice().reverse().find(c=>c.tc<t-0.02);if(c)selectComment(c.id)}
/* ── captions / transcript ── */
function toggleCC(){VW.cc=!VW.cc;const b=$('#bCC');if(b)b.classList.toggle('on',VW.cc);if(VW.cc&&!cues().length){VW.cc=false;b&&b.classList.remove('on');return toast('No captions yet','Upload',()=>uploadCaptions(VW.a))}VW.ccEl.hidden=!VW.cc;updateCC(curTime())}
function cues(){const a=VW.a;const cap=(a.captions||[])[0];if(cap)return cap.cues;if(a.transcript)return a.transcript.segs.map(s=>({s:s.s,e:s.e,text:s.text}));return[]}
function updateCC(t){const c=cues().find(x=>t>=x.s&&t<=x.e);VW.ccEl.textContent=c?c.text:'';VW.ccEl.hidden=!VW.cc||!c}
function parseCaptions(txt){const lines=txt.replace(/\r/g,'').split('\n');const out=[];let i=0;const tc=s=>{const m=s.trim().match(/(\d+):(\d+):(\d+)[.,](\d+)|(\d+):(\d+)[.,](\d+)/);if(!m)return null;return m[1]!=null?(+m[1]*3600+ +m[2]*60+ +m[3]+ +m[4]/1000):(+m[5]*60+ +m[6]+ +m[7]/1000)};while(i<lines.length){const l=lines[i];if(l.includes('-->')){const [a,b]=l.split('-->');const s=tc(a),e=tc(b);i++;const t=[];while(i<lines.length&&lines[i].trim()){t.push(lines[i].replace(/<[^>]+>/g,''));i++}if(s!=null)out.push({s,e:e!=null?e:s+3,text:t.join(' ').trim()})}else i++}return out}
function uploadCaptions(a){const inp=$('#capIn');inp.value='';inp.onchange=async()=>{const f=inp.files[0];if(!f)return;const cuesL=parseCaptions(await f.text());if(!cuesL.length)return toast('No cues found in that file');a.captions=[{id:uid(),name:f.name,lang:'English (US)',cues:cuesL}];if(!a.transcript)a.transcript={lang:'English (US)',source:f.name,segs:cuesL.map(c=>({s:c.s,e:c.e,text:c.text,spk:null}))};save();toast('Captions added');if(VW&&VW.a===a){buildLeft();if(VW.trx)$('#lpanel').classList.add('on')}};inp.click()}
async function generateTranscript(a){const v=cur(a);modal(`<h3>Generate Transcript<button class="x">✕</button></h3><p id="gtMsg">Sending audio to the local transcription server…</p><div class="uprow"><div class="bar"><i id="gtBar" style="width:10%"></i></div></div><div class="btns"><button class="btn ghost" id="gtNo">Cancel</button></div>`,{sticky:true});$('#gtNo').onclick=closeModal;try{const file=await DB.loadMedia(v.id,v.media);if(!file)throw new Error('Media not available');const fd=new FormData();fd.append('file',file,v.srcName);fd.append('speakers',a.labelSpeakers?'1':'0');$('#gtBar').style.width='40%';const r=await fetch(API+'/transcribe',{method:'POST',body:fd});if(!r.ok)throw new Error('Server replied '+r.status);const j=await r.json();const segs=(j.segments||[]).map(s=>({s:+s.start,e:+s.end,text:(s.text||'').trim(),spk:s.speaker||null}));if(!segs.length)throw new Error('No speech found');a.transcript={lang:j.language||'English (US)',source:'auto',segs};save();closeModal();toast('Transcript ready');if(VW&&VW.a===a){buildLeft();VW.trx=true;$('#lpanel').classList.add('on')}}catch(e){$('#gtMsg').innerHTML=`Could not transcribe automatically (${esc(e.message)}).<br><br>Start the Library server (it bundles the transcription endpoint), or upload an .srt / .vtt caption file exported from Premiere’s Text panel.`;$('#gtBar').style.width='0';$('.btns','#modal').innerHTML=`<button class="btn ghost" id="gtNo">Close</button><button class="btn gold" id="gtUp">Upload Caption File</button>`;$('#gtNo').onclick=closeModal;$('#gtUp').onclick=()=>{closeModal();uploadCaptions(a)}}}
function toggleTranscript(){VW.trx=!VW.trx;$('#lpanel').classList.toggle('on',VW.trx);const b=$('#bTrx');if(b)b.classList.toggle('on',VW.trx);layoutStage()}
function buildLeft(){const lp=$('#lpanel');if(!lp||!VW)return;const a=VW.a,tr=a.transcript;lp.innerHTML=`<div class="phead"><b>Transcript & Captions</b>${tr?`<button class="ib" id="trxMore" title="More options">${ico('more')}</button>`:''}<button class="ib" id="trxX" title="Close">${ico('x')}</button></div>`+(tr?`<div class="trx-search"><input id="trxQ" placeholder="Search transcript"><select id="trxLang" style="background:#1b1b20;border:1px solid var(--line2);border-radius:7px;color:var(--fg);padding:0 6px">${[tr.lang].concat(tr.langs||[]).map(l=>`<option>${esc(l)}</option>`).join('')}</select></div><div class="trx" id="trx">${tr.segs.map((s,i)=>`<button class="seg" data-i="${i}"><span class="t">${fmtTC(s.s,VW.fps,'standard')}</span>${s.spk?`<span class="spk">${esc(s.spk)}:</span>`:''}<span class="tx">${esc(s.text)}</span></button>`).join('')}</div>`:`<div class="trx-empty"><div class="lines"><i></i><i></i><i></i></div><h4>No Transcript</h4><div class="row"><select id="trxLangSel"><option>English (US)</option><option>English (UK)</option><option>Spanish</option><option>French</option><option>German</option><option>Portuguese</option><option>Japanese</option></select><button class="btn gold sm" id="trxGen">Transcribe</button></div><label style="display:flex;align-items:center;gap:6px;font-size:12.5px"><input type="checkbox" id="trxSpk" ${a.labelSpeakers?'checked':''}> Label Speakers</label><small>Transcripts are generated on this Mac. Accuracy depends on the audio — review before publishing.</small><button class="btn ghost sm" id="trxUp">Upload captions (.srt / .vtt)</button><button class="tb" id="trxFb" style="font-size:12px">Submit feedback</button></div>`);
 $('#trxX',lp).onclick=toggleTranscript;const g=$('#trxGen',lp);if(g)g.onclick=()=>{a.labelSpeakers=$('#trxSpk',lp).checked;a.transcriptLang=$('#trxLangSel',lp).value;generateTranscript(a)};const up=$('#trxUp',lp);if(up)up.onclick=()=>uploadCaptions(a);const fb=$('#trxFb',lp);if(fb)fb.onclick=()=>toast('Thanks — feedback noted');
 if(tr){$$('.seg',lp).forEach(b=>b.onclick=()=>{if(b.isContentEditable)return;seek(tr.segs[+b.dataset.i].s)});$('#trxQ',lp).oninput=e=>{const q=e.target.value.toLowerCase();$$('.seg',lp).forEach(b=>{const s=tr.segs[+b.dataset.i];const hit=!q||s.text.toLowerCase().includes(q);b.style.display=hit?'':'none';$('.tx',b).innerHTML=q&&hit?esc(s.text).replace(new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'ig'),m=>`<mark>${m}</mark>`):esc(s.text)})};
  $('#trxMore',lp).onclick=e=>menu(e.currentTarget,[{n:'Auto-scrolling',toggle:S.prefs.autoScroll!==false,keep:true,fn:(e,el)=>{S.prefs.autoScroll=S.prefs.autoScroll===false;save();$('.tog',el).classList.toggle('on')}},{n:'Export',ic:'dl',sub:ico('chev'),keep:true,fn:(e,el)=>menu(el,[{n:'Plain text (.txt)',fn:()=>exportTranscript('txt')},{n:'SubRip (.srt)',fn:()=>exportTranscript('srt')},{n:'WebVTT (.vtt)',fn:()=>exportTranscript('vtt')},{n:'CSV',fn:()=>exportTranscript('csv')}])},{n:'Edit',ic:'edit',fn:editTranscript},{n:'Add Transcript Language',ic:'globe',fn:()=>prompt2('Add transcript language','Language','Spanish',l=>{if(!l)return;tr.langs=(tr.langs||[]).concat(l);save();toast('Upload a caption file in '+l+' to fill it in');buildLeft()},'Add')},{n:'Upload Captions',ic:'cc',fn:()=>uploadCaptions(a)},{n:'Submit Feedback',ic:'note',fn:()=>toast('Thanks — feedback noted')},'-',{n:'Remove',ic:'trash',danger:true,fn:()=>confirmBox('Remove transcript?','Captions generated from it are removed too.','Remove',()=>{a.transcript=null;a.captions=[];save();buildLeft()})}])}}
function highlightTranscript(t){const tr=VW.a.transcript;if(!tr)return;const i=tr.segs.findIndex(s=>t>=s.s&&t<=s.e);$$('#trx .seg').forEach(b=>{const on=+b.dataset.i===i;if(on!==b.classList.contains('on')){b.classList.toggle('on',on);if(on&&S.prefs.autoScroll!==false)b.scrollIntoView({block:'center',behavior:'smooth'})}})}
function editTranscript(){const tr=VW.a.transcript;$$('#trx .seg').forEach(b=>{const tx=$('.tx',b);tx.contentEditable='true';b.contentEditable='false';tx.contentEditable='true';tx.style.outline='1px dashed rgba(215,159,70,.5)';tx.onblur=()=>{tr.segs[+b.dataset.i].text=tx.textContent.trim();save()}});toast('Editing transcript — click any line to change it, click away to save')}
function exportTranscript(fmt){const tr=VW.a.transcript;const srtT=s=>{const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=Math.floor(s%60),ms=Math.round((s%1)*1000);return`${pad(h)}:${pad(m)}:${pad(x)}${fmt==='vtt'?'.':','}${String(ms).padStart(3,'0')}`};let out='';if(fmt==='txt')out=tr.segs.map(s=>(s.spk?s.spk+': ':'')+s.text).join('\n');else if(fmt==='csv')out='start,end,speaker,text\n'+tr.segs.map(s=>`${s.s.toFixed(2)},${s.e.toFixed(2)},"${(s.spk||'').replace(/"/g,'""')}","${s.text.replace(/"/g,'""')}"`).join('\n');else out=(fmt==='vtt'?'WEBVTT\n\n':'')+tr.segs.map((s,i)=>`${i+1}\n${srtT(s.s)} --> ${srtT(s.e)}\n${s.spk?s.spk+': ':''}${s.text}\n`).join('\n');dlBlob(new Blob([out],{type:'text/plain'}),`${VW.a.name}.${fmt}`)}
/* ── right panel: comments + fields ── */
function buildPanel(){const vp=$('#vpanel');if(!vp||!VW)return;const {a,share}=VW;vp.innerHTML=`<div class="ptabs"><button class="${VW.tab==='comments'?'on':''}" data-tab="comments">Comments</button><button class="${VW.tab==='fields'?'on':''}" data-tab="fields">Fields</button></div><div id="ptab" style="display:flex;flex-direction:column;flex:1;min-height:0"></div>`;$$('[data-tab]',vp).forEach(b=>b.onclick=()=>{VW.tab=b.dataset.tab;buildPanel()});if(VW.tab==='comments')buildComments();else buildFields()}
const allComments=()=>(VW.a.comments||[]).filter(c=>!c.deleted&&(c.vid==null||c.vid===VW.v.id||VW.allVer));
function visibleComments(){let list=allComments();if(VW.guest)list=list.filter(c=>c.vis==='public');const f=VW.filters;if(f.has('annotations'))list=list.filter(c=>c.ann);if(f.has('attachments'))list=list.filter(c=>c.atts&&c.atts.length);if(f.has('completed'))list=list.filter(c=>c.done);if(f.has('incomplete'))list=list.filter(c=>!c.done);if(f.has('unread'))list=list.filter(c=>!c.readBy||!c.readBy.includes(who()));if(f.has('mentions'))list=list.filter(c=>c.text.includes('@'+who())||(c.replies||[]).some(r=>r.text.includes('@'+who()))||Object.values(c.reactions||{}).some(u=>u.includes(who())));if(VW.hashtag)list=list.filter(c=>c.text.toLowerCase().includes('#'+VW.hashtag.toLowerCase()));if(VW.person)list=list.filter(c=>c.by===VW.person);if(VW.q){const q=VW.q.toLowerCase();list=list.filter(c=>c.text.toLowerCase().includes(q)||c.by.toLowerCase().includes(q)||(c.replies||[]).some(r=>r.text.toLowerCase().includes(q)))}const s=VW.sort;list.sort((x,y)=>s==='timecode'?((x.tc==null?1e9:x.tc)-(y.tc==null?1e9:y.tc))||x.at-y.at:s==='oldest'?x.at-y.at:s==='newest'?y.at-x.at:s==='commenter'?x.by.localeCompare(y.by)||x.at-y.at:(x.done===y.done?x.at-y.at:x.done?1:-1));return list}
function buildComments(){const vp=$('#ptab');const {a,share}=VW;const list=visibleComments();const canComment=!share||share.perms.comments;const fl=VW.filters.size+(VW.hashtag?1:0)+(VW.person?1:0);
 vp.innerHTML=`<div class="phead"><b>${fl?'Filtered':'All comments'} (${list.length})</b><button class="ib ${fl?'on':''}" id="cFilter" title="Filter">${ico('filter')}</button><select id="cSort" title="Sort"><option value="timecode">Timecode (Default)</option><option value="oldest">Oldest</option><option value="newest">Newest</option><option value="commenter">Commenter</option><option value="completed">Completed</option></select><button class="ib" id="cSearchB" title="Search comments">${ico('search')}</button><button class="ib" id="cMore" title="More">${ico('more')}</button></div><div class="trx-search" id="cSearchRow" ${VW.q||VW.qOpen?'':'hidden'}><input id="cQ" placeholder="Search comments" value="${esc(VW.q)}"></div><div class="plist" id="cList">${list.length?list.map(commentHTML).join(''):`<div class="empty" style="padding:50px 16px"><h3 style="font-size:20px">No comments – yet</h3><p style="font-size:13px">${canComment?'Leave a note at a timecode, draw on the frame, or @mention a teammate.':'Comments are turned off for this share link.'}</p>${canComment?`<button class="btn gold sm" id="cStart">Get Started</button>`:''}</div>`}</div>${canComment?`<div class="composer" id="composer"></div>`:''}`;
 $('#cSort').value=VW.sort;$('#cSort').onchange=e=>{VW.sort=e.target.value;buildComments()};$('#cSearchB').onclick=()=>{VW.qOpen=!VW.qOpen;if(!VW.qOpen)VW.q='';buildComments();const q=$('#cQ');if(q&&VW.qOpen)q.focus()};const q=$('#cQ');if(q)q.oninput=e=>{VW.q=e.target.value;const l=$('#cList');l.innerHTML=visibleComments().map(commentHTML).join('')||'<div class="empty" style="padding:30px"><p>No matches</p></div>';bindComments()};
 $('#cFilter').onclick=e=>filterMenu(e.currentTarget);$('#cMore').onclick=e=>menu(e.currentTarget,[{n:'Copy Comments',ic:'copy',fn:copyComments},{n:'Paste Comments',ic:'paste',fn:pasteComments,dis:!canComment},{n:'Print Comments',ic:'print',fn:printComments},{n:'Export Comments',ic:'dl',sub:ico('chev'),keep:true,fn:(e,el)=>menu(el,[{n:'CSV',fn:()=>exportComments('csv')},{n:'Plain text',fn:()=>exportComments('txt')},{n:'Premiere markers (CSV)',fn:()=>exportComments('premiere')}])},{html:'<div class="note">Only comments visible with the current filters are copied, printed or exported.</div>'},'-',{n:VW.allVer?'Hide other versions’ comments':'Show comments from all versions',ic:'layers',fn:()=>{VW.allVer=!VW.allVer;buildComments()}},{n:'Mark all as read',ic:'check',fn:()=>{allComments().forEach(c=>{c.readBy=[...new Set((c.readBy||[]).concat(who()))]});save();buildComments()}}],{align:'right'});
 const cs=$('#cStart');if(cs)cs.onclick=()=>$('#cText').focus();bindComments();if(canComment)buildComposer();drawMarks()}
function filterMenu(anchor){const f=VW.filters;const tg=(k,n)=>({n,tick:true,on:f.has(k),keep:true,fn:(e,el)=>{f.has(k)?f.delete(k):f.add(k);el.classList.toggle('on',f.has(k));buildComments()}});const tags=[...new Set(allComments().flatMap(c=>(c.text.match(/#\w+/g)||[]).map(t=>t.slice(1))))];const ppl=[...new Set(allComments().map(c=>c.by))];menu(anchor,[{h:'Filter'},tg('annotations','Annotations'),tg('attachments','Attachments'),tg('completed','Completed'),tg('incomplete','Incomplete'),tg('unread','Unread'),tg('mentions','Mentions and reactions'),'-',{n:'Hashtag'+(VW.hashtag?': #'+VW.hashtag:''),ic:'hash',sub:ico('chev'),keep:true,fn:(e,el)=>menu(el,tags.length?tags.map(t=>({n:'#'+t,tick:true,on:VW.hashtag===t,fn:()=>{VW.hashtag=VW.hashtag===t?null:t;buildComments()}})):[{n:'No hashtags used',dis:true}])},{n:'Person'+(VW.person?': '+VW.person:''),ic:'person',sub:ico('chev'),keep:true,fn:(e,el)=>menu(el,ppl.map(p=>({n:p,tick:true,on:VW.person===p,fn:()=>{VW.person=VW.person===p?null:p;buildComments()}})))},'-',{n:'Clear Filters',ic:'x',fn:()=>{f.clear();VW.hashtag=null;VW.person=null;buildComments()}}],{w:230})}
function fmtText(t){return esc(t).replace(/@([A-Z][\w]+(?:\s[A-Z][\w]+)?)/g,'<span class="mention">@$1</span>').replace(/(^|\s)(#\w+)/g,'$1<span class="tag">$2</span>').replace(/(https?:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" style="color:var(--info);text-decoration:underline">$1</a>')}
function commentHTML(c){const me=who();const unread=!(c.readBy||[]).includes(me)&&c.by!==me;const n=allComments().indexOf(c)+1;const rx=Object.entries(c.reactions||{}).filter(([,u])=>u.length);return`<div class="cm ${c.done?'done':''} ${VW.sel===c.id?'on':''}" data-c="${c.id}">${unread?'<i class="unread"></i>':''}<div class="hd">${avatar(c.by,c.by===ME.name?'':'b')}<span class="who">${esc(c.by)}</span><span class="when">${ago(c.at)}</span>${c.tc!=null?`<span class="tcchip" data-tc="${c.tc}">${c.ann?'✎ ':''}${fmtTC(c.tc,VW.fps,S.prefs.tcmode)}${c.tcEnd!=null?' – '+fmtTC(c.tcEnd,VW.fps,S.prefs.tcmode):''}</span>`:''}${c.vis!=='public'?`<span class="vis">${ico('lock')}${c.vis==='team'?'Team':'Internal'}</span>`:''}<span class="done-chk" data-done="${c.id}" title="${c.done?'Mark incomplete':'Mark complete'}">${c.done?'✓':''}</span><button class="mo" data-cmo="${c.id}">${ico('more')}</button></div><div class="tx">${fmtText(c.text)}</div>${c.ann?`<div class="ann-th" data-annth="${c.id}"><img alt="annotation"></div>`:''}${c.atts&&c.atts.length?`<div class="atts">${c.atts.map(at=>`<span class="att" data-att="${at.id}" title="Download">${at.thumb?`<img data-attimg="${at.id}">`:ico('att')}${esc(at.name)}</span>`).join('')}</div>`:''}<div class="ft">${rx.map(([e,u])=>`<span class="react ${u.includes(me)?'me':''}" data-rx="${esc(e)}">${e} ${u.length}</span>`).join('')}<button data-react="${c.id}" title="React">${ico('smile').replace('<svg','<svg style="width:14px;height:14px"')}</button><button data-reply="${c.id}">Reply</button>${c.tcEnd!=null?`<span class="dur">${fmtDur(c.tcEnd-c.tc)}</span>`:''}</div>${(c.replies||[]).length?`<div class="replies">${c.replies.map(r=>`<div class="reply" data-r="${r.id}"><span class="who">${esc(r.by)}</span> <span class="when">${ago(r.at)}</span><div class="tx">${fmtText(r.text)}</div></div>`).join('')}</div>`:''}<div class="replybox" id="rb-${c.id}" hidden></div></div>`}
function bindComments(){const l=$('#cList');if(!l)return;$$('.cm',l).forEach(el=>{const c=allComments().find(x=>x.id===el.dataset.c);if(!c)return;el.onclick=e=>{if(e.target.closest('[data-done],[data-cmo],[data-reply],[data-react],.react,.att,.replybox,a'))return;selectComment(c.id)};
  const th=$('[data-annth] img',el);if(th)DB.get('thumbs','ann_'+c.id).then(b=>{if(b)th.src=URL.createObjectURL(b)});
  $$('[data-attimg]',el).forEach(im=>DB.get('thumbs','att_'+im.dataset.attimg).then(b=>{if(b)im.src=URL.createObjectURL(b)}));
  $$('.att',el).forEach(at=>at.onclick=async e=>{e.stopPropagation();const f=await DB.get('blobs','att_'+at.dataset.att);if(f)dlBlob(f,c.atts.find(x=>x.id===at.dataset.att).name)});
  $$('.react',el).forEach(r=>r.onclick=e=>{e.stopPropagation();react(c,r.dataset.rx)});
  $('[data-react]',el).onclick=e=>{e.stopPropagation();emojiPicker(e.currentTarget,em=>react(c,em))};
  $('[data-done]',el).onclick=e=>{e.stopPropagation();c.done=!c.done;c.doneBy=who();save();log((c.done?'completed':'reopened')+' a comment on '+VW.a.name);buildComments()};
  $('[data-reply]',el).onclick=e=>{e.stopPropagation();replyBox(c)};
  $('[data-cmo]',el).onclick=e=>{e.stopPropagation();commentMenu(e.currentTarget,c)}})}
function replyBox(c){const rb=$('#rb-'+c.id);rb.hidden=false;rb.innerHTML=`<div style="display:flex;gap:6px;margin-top:8px"><textarea rows="1" placeholder="Reply…" style="flex:1;background:rgba(0,0,0,.3);border:1px solid var(--line2);border-radius:7px;padding:6px 8px;color:var(--fg);font-size:13px;resize:none"></textarea><button class="send">${ico('send')}</button></div>`;const ta=$('textarea',rb);ta.focus();const send=()=>{const t=ta.value.trim();if(!t)return;c.replies=c.replies||[];c.replies.push({id:uid(),by:who(),at:Date.now(),text:t});save();notify(`${who()} replied on ${VW.a.name}: “${t.slice(0,60)}”`,'#/view/'+VW.a.id+'?c='+c.id,who());buildComments()};$('.send',rb).onclick=send;ta.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}if(e.key==='Escape'){rb.hidden=true}}}
function react(c,em){c.reactions=c.reactions||{};const u=c.reactions[em]=c.reactions[em]||[];const i=u.indexOf(who());if(i>=0)u.splice(i,1);else u.push(who());save();buildComments()}
function emojiPicker(anchor,fn){const p=pop(anchor,`<div class="emoji">${EMOJIS.map(e=>`<button>${e}</button>`).join('')}</div>`,{w:300});$$('button',p).forEach(b=>b.onclick=()=>{closePop();fn(b.textContent)})}
function commentMenu(anchor,c){const mine=c.by===who()||!VW.guest;menu(anchor,[{n:c.done?'Mark incomplete':'Mark complete',ic:'check',fn:()=>{c.done=!c.done;save();buildComments()}},{n:'Copy comment link',ic:'link',fn:()=>copyText(APP_PATH+'#/view/'+VW.a.id+'?c='+c.id,'Link copied')},{n:'Copy text',ic:'copy',fn:()=>copyText(c.text)},{n:'Go to timecode',ic:'clock',dis:c.tc==null,fn:()=>selectComment(c.id)},'-',{h:'Visibility'},...['public','internal','team'].map(v=>({n:v==='public'?'Public':v==='internal'?'Internal':'Team',tick:true,on:c.vis===v,dis:VW.guest,fn:()=>{c.vis=v;save();buildComments()}})),'-',{n:'Edit',ic:'edit',dis:!mine,fn:()=>editComment(c)},{n:'Delete',ic:'trash',danger:true,dis:!mine,fn:()=>confirmBox('Delete comment?','Replies are deleted too.','Delete',()=>{c.deleted=true;save();buildComments()})}],{align:'right'})}
function editComment(c){modal(`<h3>Edit comment<button class="x">✕</button></h3><textarea id="ecT" rows="4">${esc(c.text)}</textarea><div class="btns"><button class="btn ghost" id="ecNo">Cancel</button><button class="btn gold" id="ecOk">Save</button></div>`);$('#ecNo').onclick=closeModal;$('#ecOk').onclick=()=>{c.text=$('#ecT').value.trim();c.edited=Date.now();save();closeModal();buildComments()}}
function selectComment(id){const c=allComments().find(x=>x.id===id);if(!c)return;VW.sel=id;c.readBy=[...new Set((c.readBy||[]).concat(who()))];save();if(c.tc!=null){if(VW.el){VW.el.pause();seek(c.tc)}}VW.shownAnn=c.ann?c.ann.shapes:null;VW.shownAt=c.tc;drawAnn();$$('#cList .cm').forEach(el=>el.classList.toggle('on',el.dataset.c===id));const el=$(`#cList .cm[data-c="${id}"]`);if(el)el.scrollIntoView({block:'nearest',behavior:'smooth'});drawMarks()}
function drawMarks(){const m=$('#tlMarks');if(!m||!VW||!VW.dur)return;m.innerHTML=visibleComments().filter(c=>c.tc!=null).map(c=>c.tcEnd!=null?`<div class="mk rng ${c.done?'done':''}" data-c="${c.id}" style="left:${c.tc/VW.dur*100}%;width:${(c.tcEnd-c.tc)/VW.dur*100}%"></div>`:`<div class="mk ${c.done?'done':''}" data-c="${c.id}" style="left:${c.tc/VW.dur*100}%" title="${esc(c.by)}: ${esc(c.text.slice(0,60))}"></div>`).join('');$$('.mk',m).forEach(k=>k.onclick=e=>{e.stopPropagation();selectComment(k.dataset.c)})}
/* composer */
function buildComposer(){const cp=$('#composer');if(!cp)return;const C=VW.comp;cp.innerHTML=`<div class="top">${C.useTc?`<span class="tchip" id="tchip" title="Remove timestamp"><span>${chipLabel()}</span><span class="x">✕</span></span>`:`<button class="tb" id="tcAdd" style="height:28px;margin-top:3px;font-size:12px">${ico('clock')}Add timestamp</button>`}<textarea id="cText" rows="1" placeholder="${VW.guest?'Leave your feedback…':'Leave a comment…'}"></textarea></div>${C.tcEnd!=null?`<div class="rangelab">Range ${fmtDur(C.tcEnd-C.tc)} · <a href="#" id="rangeClr" style="color:var(--acc)">clear</a></div>`:''}<div class="attlist" id="attList"></div><div class="bot"><button class="ib" id="cAtt" title="Add an attachment">${ico('att')}</button><button class="ib" id="cEmo" title="Add an emoji">${ico('smile')}</button><button class="ib ${VW.draw.on?'on':''}" id="cDraw" title="Draw an annotation (D)">${ico('draw')}</button>${VW.guest?'':`<button class="visb" id="cVis">${ico(C.vis==='public'?'globe':'lock')}${C.vis==='public'?'Public':C.vis==='internal'?'Internal':'Team'}${ico('down')}</button>`}${VW.guest?'<span class="sp"></span>':''}<button class="send" id="cSend" title="Submit (Enter)" disabled>${ico('send')}</button></div><div class="anntools" id="annTools" ${VW.draw.on?'':'hidden'}>${[['arrow','Arrow'],['line','Line'],['rect','Rectangle'],['pen','Pen']].map(([t,n])=>`<button class="ib ${VW.draw.tool===t?'on':''}" data-tool="${t}" title="${n}">${ico(t)}</button>`).join('')}<span class="tb-sep"></span>${ANN_COLORS.map(c=>`<span class="sw ${VW.draw.color===c?'on':''}" data-col="${c}" style="background:${c}"></span>`).join('')}<span class="tb-sep"></span><button class="ib" id="annUndo" title="Undo">${ico('undo')}</button><button class="ib" id="annRedo" title="Redo">${ico('redo')}</button><span class="sp"></span><button class="ib" id="annX" title="Close annotation">${ico('x')}</button></div>`;
 const ta=$('#cText',cp);ta.oninput=()=>{ta.style.height='auto';ta.style.height=Math.min(160,ta.scrollHeight)+'px';$('#cSend').disabled=!ta.value.trim()&&!VW.draw.shapes.length;mentionCheck(ta)};ta.onfocus=()=>{if(VW.el&&!VW.el.paused&&!VW.comp.locked){VW.comp.locked=true;VW.comp.tc=VW.range.in!=null?VW.range.in:curTime();$('#tchip')&&( $('#tchip').firstChild.textContent=chipLabel())}};ta.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!$('.mentions',cp)){e.preventDefault();submitComment()}if(e.key==='Escape')ta.blur()};
 const ch=$('#tchip',cp);if(ch)ch.onclick=e=>{if(e.target.classList.contains('x')){C.useTc=false;C.locked=false;buildComposer()}else{VW.comp.locked=true;C.tc=curTime();ch.firstChild.textContent=chipLabel()}};const ad=$('#tcAdd',cp);if(ad)ad.onclick=()=>{C.useTc=true;C.locked=false;buildComposer()};const rc=$('#rangeClr',cp);if(rc)rc.onclick=e=>{e.preventDefault();clearRange()};
 $('#cAtt',cp).onclick=()=>{const inp=$('#attIn');inp.value='';inp.onchange=()=>{[...inp.files].forEach(f=>C.atts.push({id:uid(),name:f.name,size:f.size,type:f.type,file:f}));renderAtts()};inp.click()};
 $('#cEmo',cp).onclick=e=>emojiPicker(e.currentTarget,em=>{ta.value+=em;ta.oninput();ta.focus()});$('#cDraw',cp).onclick=()=>toggleDraw();const vb=$('#cVis',cp);if(vb)vb.onclick=e=>menu(e.currentTarget,[{n:'Public Comment',ic:'globe',sub:'',tick:true,on:C.vis==='public',fn:()=>{C.vis='public';buildComposer()}},{html:'<div class="note">Visible to all members and share link viewers</div>'},{n:'Internal Comment',ic:'lock',tick:true,on:C.vis==='internal',fn:()=>{C.vis='internal';buildComposer()}},{html:'<div class="note">Only members with access to this project</div>'},{n:'Team',ic:'users',tick:true,on:C.vis==='team',fn:()=>{C.vis='team';buildComposer()}},{html:'<div class="note">Only your team, never share link viewers</div>'}],{above:true,w:260});
 $('#cSend',cp).onclick=submitComment;$$('[data-tool]',cp).forEach(b=>b.onclick=()=>{VW.draw.tool=b.dataset.tool;$$('[data-tool]',cp).forEach(x=>x.classList.toggle('on',x===b))});$$('[data-col]',cp).forEach(s=>s.onclick=()=>{VW.draw.color=s.dataset.col;$$('[data-col]',cp).forEach(x=>x.classList.toggle('on',x===s))});$('#annUndo',cp).onclick=()=>{const s=VW.draw.shapes.pop();if(s)VW.draw.redo.push(s);drawAnn();updateComposer()};$('#annRedo',cp).onclick=()=>{const s=VW.draw.redo.pop();if(s)VW.draw.shapes.push(s);drawAnn();updateComposer()};$('#annX',cp).onclick=()=>toggleDraw(false);renderAtts()}
function updateComposer(){const s=$('#cSend');const ta=$('#cText');if(s&&ta)s.disabled=!ta.value.trim()&&!VW.draw.shapes.length;const ch=$('#tchip');if(ch)ch.firstChild.textContent=chipLabel();const rl=$('.rangelab');if((VW.comp.tcEnd!=null)!==!!rl)buildComposer()}
function renderAtts(){const l=$('#attList');if(!l)return;l.innerHTML=VW.comp.atts.map(a=>`<span>${ico('att')}${esc(a.name)} <b data-rm="${a.id}" style="cursor:pointer;color:var(--mut)">✕</b></span>`).join('');$$('[data-rm]',l).forEach(b=>b.onclick=()=>{VW.comp.atts=VW.comp.atts.filter(a=>a.id!==b.dataset.rm);renderAtts()})}
function toggleDraw(on){if(!VW.el&&!$('.stage img.still'))return toast('Annotations need a video or image');on=on==null?!VW.draw.on:on;VW.draw.on=on;if(on){if(VW.el)VW.el.pause();VW.comp.locked=true;VW.comp.tc=curTime();VW.comp.useTc=true}else{VW.draw.shapes=[];VW.draw.redo=[]}$('#stage').classList.toggle('drawing',on);const t=$('#annTools');if(t)t.hidden=!on;const b=$('#cDraw');if(b)b.classList.toggle('on',on);drawAnn();drawPins();updateComposer()}
function mentionCheck(ta){const cp=ta.closest('.composer');const old=$('.mentions',cp);if(old)old.remove();const m=ta.value.slice(0,ta.selectionStart).match(/@(\w*)$/);if(!m)return;const q=m[1].toLowerCase();const list=people().filter(p=>p.toLowerCase().startsWith(q)&&p!==who());if(!list.length)return;const d=document.createElement('div');d.className='mentions';d.innerHTML=list.map(p=>`<div>${avatar(p)} ${esc(p)}</div>`).join('');cp.style.position='relative';cp.appendChild(d);$$('div',d).forEach((el,i)=>el.onclick=()=>{ta.value=ta.value.slice(0,ta.selectionStart-m[0].length)+'@'+list[i]+' '+ta.value.slice(ta.selectionStart);d.remove();ta.focus();ta.oninput()})}
async function submitComment(){const ta=$('#cText');const text=ta.value.trim();const C=VW.comp;if(!text&&!VW.draw.shapes.length)return;if(VW.guest&&!guestName()){return askGuestName(submitComment)}const c={id:uid(),vid:VW.v.id,by:who(),at:Date.now(),text,tc:C.useTc?C.tc:null,tcEnd:C.useTc&&C.tcEnd!=null?C.tcEnd:null,vis:VW.guest?'public':C.vis,done:false,reactions:{},replies:[],atts:[],readBy:[who()]};
 if(VW.draw.shapes.length){c.ann={shapes:clone(VW.draw.shapes)};const cv=frameCanvas(VW.draw.shapes);if(cv){const b=await new Promise(r=>cv.toBlob(r,'image/jpeg',.8));await DB.put('thumbs','ann_'+c.id,b)}else{const cv2=document.createElement('canvas');cv2.width=640;cv2.height=360;const x=cv2.getContext('2d');x.fillStyle='#000';x.fillRect(0,0,640,360);drawShapes(x,VW.draw.shapes,640,360);await DB.put('thumbs','ann_'+c.id,await new Promise(r=>cv2.toBlob(r,'image/jpeg',.8)))}}
 for(const at of C.atts){const a={id:at.id,name:at.name,size:at.size,type:at.type};await DB.put('blobs','att_'+at.id,at.file);if(at.type.startsWith('image/')){try{const img=await loadImg(URL.createObjectURL(at.file));await DB.put('thumbs','att_'+at.id,await canvasBlob(img,img.naturalWidth,img.naturalHeight,160));a.thumb=true}catch(e){}}c.atts.push(a)}
 VW.a.comments=VW.a.comments||[];VW.a.comments.push(c);save();log('commented on '+VW.a.name);if(S.prefs.nComments!==false)notify(`${who()} commented on ${VW.a.name}${c.tc!=null?' at '+fmtTC(c.tc,VW.fps,'timecode'):''}: “${text.slice(0,60)}”`,'#/view/'+VW.a.id+'?c='+c.id,who());(text.match(/@([A-Z]\w+(?:\s[A-Z]\w+)?)/g)||[]).forEach(mn=>notify(`${who()} mentioned ${mn.slice(1)} on ${VW.a.name}`,'#/view/'+VW.a.id+'?c='+c.id,who()));if(VW.share){VW.share.activity.unshift({at:Date.now(),who:who(),what:'commented on '+VW.a.name})}
 C.atts=[];C.locked=false;C.tcEnd=null;if(VW.draw.on)toggleDraw(false);clearRange();buildComments();selectComment(c.id);toast('Comment added')}
function askGuestName(then){modal(`<h3>Who’s reviewing?<button class="x">✕</button></h3><p>Your name shows next to your comments.</p><label>Name</label><input type="text" id="gnIn" placeholder="e.g. Eric"><label>Email (optional)</label><input type="text" id="gnMail"><div class="btns"><button class="btn gold" id="gnOk">Continue</button></div>`);$('#gnOk').onclick=()=>{const n=$('#gnIn').value.trim();if(!n)return;try{localStorage.setItem('bm.review.guest',n);localStorage.setItem('bm.review.guestmail',$('#gnMail').value.trim())}catch(e){}closeModal();then&&then()}}
function commentsText(fmt){const list=visibleComments();if(fmt==='csv')return'Timecode,Commenter,Date,Comment,Completed,Replies\n'+list.map(c=>[c.tc!=null?fmtTC(c.tc,VW.fps,'timecode'):'',c.by,new Date(c.at).toISOString(),c.text,c.done?'yes':'no',(c.replies||[]).map(r=>r.by+': '+r.text).join(' | ')].map(x=>`"${String(x).replace(/"/g,'""')}"`).join(',')).join('\n');if(fmt==='premiere')return'Marker Name,Description,In,Out,Duration,Marker Type\n'+list.filter(c=>c.tc!=null).map(c=>[c.by,c.text.replace(/\n/g,' '),fmtTC(c.tc,VW.fps,'timecode').replace(';',':'),fmtTC(c.tcEnd!=null?c.tcEnd:c.tc,VW.fps,'timecode').replace(';',':'),fmtTC((c.tcEnd||c.tc)-c.tc,VW.fps,'timecode').replace(';',':'),'Comment'].map(x=>`"${String(x).replace(/"/g,'""')}"`).join(',')).join('\n');return list.map(c=>`${c.tc!=null?fmtTC(c.tc,VW.fps,'timecode')+' - ':''}${c.by}: ${c.text}${c.done?' [completed]':''}${(c.replies||[]).map(r=>`\n    ↳ ${r.by}: ${r.text}`).join('')}`).join('\n')}
function exportComments(fmt){dlBlob(new Blob([commentsText(fmt)],{type:'text/plain'}),`${VW.a.name} comments.${fmt==='txt'?'txt':'csv'}`)}
function copyComments(){copyText(commentsText('txt'),'Comments copied')}
async function pasteComments(){let txt='';try{txt=await navigator.clipboard.readText()}catch(e){}if(!txt){prompt2('Paste comments','One per line: HH:MM:SS:FF - Name: text','',t=>t&&importComments(t));return}importComments(txt)}
function importComments(txt){let n=0;txt.split('\n').forEach(l=>{const m=l.match(/^\s*(?:(\d[\d:;.]+)\s*-\s*)?(?:([^:]{1,40}):\s*)?(.+)$/);if(!m)return;const tc=m[1]?parseTC(m[1],VW.fps):null;VW.a.comments.push({id:uid(),vid:VW.v.id,by:(m[2]||who()).trim(),at:Date.now(),text:m[3].trim(),tc,tcEnd:null,vis:'public',done:false,reactions:{},replies:[],atts:[],readBy:[who()]});n++});save();buildComments();toast(`Pasted ${n} comment${n===1?'':'s'}`)}
function printComments(){const w=window.open('','_blank');if(!w)return toast('Pop-up blocked — allow pop-ups to print');w.document.write(`<title>${esc(VW.a.name)} — comments</title><style>body{font:13px -apple-system,sans-serif;padding:24px}h1{font-size:18px}div{padding:8px 0;border-bottom:1px solid #ddd}b{font-family:monospace}</style><h1>${esc(VW.a.name)} — ${visibleComments().length} comments</h1>`+visibleComments().map(c=>`<div><b>${c.tc!=null?fmtTC(c.tc,VW.fps,'timecode'):'—'}</b> &nbsp; <strong>${esc(c.by)}</strong> · ${fmtDate(c.at,true)}${c.done?' · ✓ completed':''}<br>${esc(c.text)}${(c.replies||[]).map(r=>`<br>&nbsp;&nbsp;↳ <strong>${esc(r.by)}</strong>: ${esc(r.text)}`).join('')}</div>`).join(''));w.document.close();w.print()}
/* ── fields tab ── */
function buildFields(){const vp=$('#ptab');const {a,share}=VW;const m=VW.v.meta||{};const fs=allFields();const grp=VW.fieldGroup;let list=fs.filter(f=>grp==='all'||(grp==='ess'&&f.g==='ess')||(grp==='file'&&f.g==='file')||(grp==='custom'&&f.g==='custom'));const q=VW.fieldQ.toLowerCase();if(q)list=list.filter(f=>f.n.toLowerCase().includes(q));if(VW.fieldFilter==='empty')list=list.filter(f=>fieldVal(f,a)==='');if(VW.fieldFilter==='filled')list=list.filter(f=>fieldVal(f,a)!=='');const counts={all:fs.length,ess:fs.filter(f=>f.g==='ess').length,file:fs.filter(f=>f.g==='file').length,custom:fs.filter(f=>f.g==='custom').length};const ro=share&&!share.fields.allowEdits;
 vp.innerHTML=`<div class="plist"><div class="fhead"><h4>${esc(a.name)}</h4><small>Created ${fmtDate(a.created,true)} · ${esc(a.uploader)}</small><div class="kv3"><div>${esc(m.vcodec||m.acodec||m.format||'—')}<small>${m.type==='Audio'?'Audio Codec':'Video Codec'}</small></div><div>${m.w?m.w+'×'+m.h:'—'}<small>Resolution</small></div><div>${m.bitrate?(m.bitrate/1e6).toFixed(2)+' Mb/s':'—'}<small>Bit Rate</small></div></div></div><div class="fgrid2"><div class="fbox"><div class="k">${ico('eye')}Seen By</div><div style="display:flex;gap:-4px">${(a.seen||[]).map(p=>avatar(p)).join('')}</div></div><div class="fbox ${ro?'':'edit'}" id="fStatus" style="${ro?'':'cursor:pointer'}"><div class="k">${ico('check')}Status</div>${statusPill(a.status)}</div></div><div class="fsel"><select id="fGroup"><option value="all">All Fields (${counts.all})</option><option value="ess">Essentials (${counts.ess})</option><option value="file">File Attributes (${counts.file})</option><option value="custom">Custom Fields (${counts.custom})</option></select><span class="sp"></span><select id="fFilter"><option value="none">None</option><option value="empty">Only Empty</option><option value="filled">Only Filled</option></select><button class="ib" id="fSearchB">${ico('search')}</button></div><div class="trx-search" ${VW.fieldQ||VW.fqOpen?'':'hidden'}><input id="fQ" placeholder="Search fields" value="${esc(VW.fieldQ)}"></div>${list.map(f=>{const editable=!ro&&(f.set||f.custom);const v=fieldVal(f,a,true);const tall=f.t==='long'||f.t==='tags'||f.t==='avatars';return`<div class="frow ${editable?'edit':''} ${tall?'tall':''}" data-fk="${f.k}">${tall?`<div class="k" style="display:flex;align-items:center;gap:6px">${ico(fieldIcon(f))}${esc(f.n)}</div><div class="v ${v?'':'emp'}">${v||(editable?'Enter '+esc(f.n.toLowerCase()):'—')}</div>`:`${ico(fieldIcon(f))}<span class="k">${esc(f.n)}</span>${f.t==='rating'?`<span class="stars">${[1,2,3,4,5].map(n=>`<b class="${n<=(a.rating||0)?'on':''}" data-star="${n}">★</b>`).join('')}</span>`:f.t==='bool'?`<span class="tog ${f.get(a)?'on':''}"></span>`:`<span class="v ${v?'':'emp'}">${v||(editable?(f.t==='num'?'Enter number':'Enter '+esc(f.n.toLowerCase())):'—')}</span>`}`}</div>`}).join('')}${!ro&&!share?`<div style="padding:8px 10px"><button class="btn ghost sm" id="fNew">${ico('plus')}New Field</button></div>`:''}</div>`;
 $('#fGroup',vp).value=grp;$('#fGroup',vp).onchange=e=>{VW.fieldGroup=e.target.value;buildFields()};$('#fFilter',vp).value=VW.fieldFilter;$('#fFilter',vp).onchange=e=>{VW.fieldFilter=e.target.value;buildFields()};$('#fSearchB',vp).onclick=()=>{VW.fqOpen=!VW.fqOpen;if(!VW.fqOpen)VW.fieldQ='';buildFields();const q=$('#fQ');if(q&&VW.fqOpen)q.focus()};const fq=$('#fQ',vp);if(fq)fq.oninput=e=>{VW.fieldQ=e.target.value;buildFields();const q=$('#fQ');q.focus();q.setSelectionRange(99,99)};
 if(!ro)$('#fStatus',vp).onclick=e=>editField(e.currentTarget,a,F.status,()=>buildFields());
 $$('.frow.edit',vp).forEach(r=>{const f=fs.find(x=>x.k===r.dataset.fk);r.onclick=e=>{const st=e.target.closest('[data-star]');if(st){f.set(a,+st.dataset.star===a.rating?null:+st.dataset.star);save();buildFields();return}editField(r,a,f,()=>buildFields())}});const fn=$('#fNew',vp);if(fn)fn.onclick=()=>newField(buildFields)}
